// 测试替身：mock——不仅替掉行为，还断言「被测代码是否按预期调用了它」
function createMockEmail() {
  const calls = [];
  return {
    send(to, subject) { calls.push({ to, subject }); },
    assertCalledOnceWith(expectedTo) {
      return calls.length === 1 && calls[0].to === expectedTo;
    },
    calls,
  };
}

function notifySignup(email, user) { email.send(user.email, "welcome"); }

const mock = createMockEmail();
notifySignup(mock, { email: "a@x.com" });
console.log(mock.assertCalledOnceWith("a@x.com"));
console.log(JSON.stringify(mock.calls));
